import{_ as a,o as i,c as t,a5 as e}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"第10章 データ構造・アルゴリズム・ゲーム数学 ── ゲームに効くものだけを深く","description":"","frontmatter":{"title":"第10章 データ構造・アルゴリズム・ゲーム数学 ── ゲームに効くものだけを深く","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"競技プログラミング全域は不要だが、空間分割・ソート・ハッシュ・ グラフ探索はゲームの毎フレームを支えている。そして3D数学(ベクトル・ 行列・クォータニオン)は、Transform、カメラ、アニメーション、"}},"headers":[],"relativePath":"guide/low-level/algorithms-and-game-math.md","filePath":"guide/low-level/algorithms-and-game-math.md"}'),r={name:"guide/low-level/algorithms-and-game-math.md"};function s(n,l,o,d,h,p){return i(),t("div",null,[...l[0]||(l[0]=[e(`<h1 id="第10章-データ構造・アルゴリズム・ゲーム数学-──-ゲームに効くものだけを深く" tabindex="-1">第10章 データ構造・アルゴリズム・ゲーム数学 ── ゲームに効くものだけを深く <a class="header-anchor" href="#第10章-データ構造・アルゴリズム・ゲーム数学-──-ゲームに効くものだけを深く" aria-label="Permalink to &quot;第10章 データ構造・アルゴリズム・ゲーム数学 ── ゲームに効くものだけを深く&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>競技プログラミング全域は不要だが、<strong>空間分割・ソート・ハッシュ・ グラフ探索</strong>はゲームの毎フレームを支えている。そして3D数学(ベクトル・ 行列・クォータニオン)は、Transform、カメラ、アニメーション、 レンダリング(第12章)の共通言語だ。ここを曖昧にしたままシェーダには進めない。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>計算量(O記法)を実測とキャッシュ効果込みで判断できる (「O(n)でも配列走査はO(log n)の木より速いことがある」を説明できる)</li><li>ゲーム頻出データ構造を自力実装できる(動的配列・ハッシュ・プール・リングバッファ)</li><li>ベクトル演算(内積・外積)の幾何的意味を即答できる</li><li>行列でモデル→ワールド→ビュー→射影の変換を組み立てられる</li><li>クォータニオンで回転を扱え、オイラー角の問題点を説明できる</li><li>A*でパス検索を実装できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第3章(キャッシュ)、第9章(C++)。高校数学(三角関数・ベクトル)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><h3 id="a-データ構造とアルゴリズム-ゲーム偏重セレクション" tabindex="-1">A. データ構造とアルゴリズム(ゲーム偏重セレクション) <a class="header-anchor" href="#a-データ構造とアルゴリズム-ゲーム偏重セレクション" aria-label="Permalink to &quot;A. データ構造とアルゴリズム(ゲーム偏重セレクション)&quot;">​</a></h3><ol><li><strong>計算量とキャッシュの現実</strong><ul><li>O記法の基礎。ただし定数項が支配する現実(第3章の回収)</li><li>「小さいnなら配列線形探索が最速」問題</li></ul></li><li><strong>ゲーム頻出のデータ構造</strong><ul><li>動的配列(vector)── 基本にして最強</li><li><strong>swap-and-pop削除</strong>(順序を捨てて O(1) 削除)── ゲームの定番イディオム</li><li>ハッシュテーブル(オープンアドレス法がキャッシュに有利)</li><li>リングバッファ(入力履歴、ネットワーク、オーディオ)</li><li>優先度キュー/ヒープ(A*、イベントスケジューラ)</li><li>侵入型リンクリスト(エンジン内部で今も現役の理由)</li><li>ハンドル配列(generation付きID)── ダングリング対策の業界標準</li></ul></li><li><strong>空間データ構造(ゲームの華)</strong><ul><li>グリッド/ユニフォームグリッド(まずこれ。実は最強なことが多い)</li><li>クアッドツリー/オクツリー、BVH(レイキャスト・カリング・物理)</li><li>空間ハッシュ</li></ul></li><li><strong>アルゴリズム</strong><ul><li>ソート: 基数ソート(描画キーソート)、std::sortの中身(introsort)</li><li>探索: BFS/DFS、<strong>A</strong>*(ヒューリスティック、ゲームAIの中核)</li><li>補間: lerp、smoothstep、イージング関数(ゲームフィールの基礎)</li><li>乱数: PCG/xorshift、シード再現性(リプレイ・デバッグ)</li></ul></li></ol><h3 id="b-ゲーム数学" tabindex="-1">B. ゲーム数学 <a class="header-anchor" href="#b-ゲーム数学" aria-label="Permalink to &quot;B. ゲーム数学&quot;">​</a></h3><ol start="5"><li><strong>ベクトル</strong><ul><li>内積 = 射影・角度・「前にいる?」判定/外積 = 法線・左右判定・面積</li><li>正規化、距離の2乗比較(sqrt回避)</li></ul></li><li><strong>行列</strong><ul><li>4x4同次座標行列。平行移動・回転・スケールの合成</li><li><strong>行優先/列優先、行ベクトル/列ベクトル規約の地獄</strong>(DirectXとOpenGLの差)</li><li>逆行列・転置、法線変換に逆転置が要る理由</li><li>モデル→ワールド→ビュー→射影→NDC→スクリーンの変換連鎖 (第12章レンダリングの数学的骨格。ここで完全に固める)</li></ul></li><li><strong>回転の表現</strong><ul><li>オイラー角(ジンバルロック・補間の破綻)</li><li>軸角、<strong>クォータニオン</strong>(q v q⁻¹、slerp、なぜ4次元で3D回転か)</li><li>回転行列との相互変換</li></ul></li><li><strong>幾何と衝突の基礎(物理エンジンの入口)</strong><ul><li>AABB/球/レイ/平面の交差判定</li><li>分離軸定理(SAT)の概念</li><li>フラスタムカリングの数式(平面6枚と AABB)</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>「アルゴリズムの理論次数」と「メモリの物理」の両輪</strong>で判断する</li><li><strong>swap-and-pop・ハンドルID・グリッド</strong> ── ゲーム業界の三種の神器</li><li><strong>内積と外積の幾何的直観</strong> ── シェーダを読む前提</li><li><strong>変換の連鎖(MVP行列)</strong> ── レンダリングの背骨</li><li><strong>クォータニオン</strong> ── アニメーション・カメラの必需品</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>「視界内の敵だけ処理」</td><td>内積・フラスタム・空間分割</td></tr><tr><td>数千体の衝突判定が間に合う</td><td>グリッド/BVHでO(n²)回避</td></tr><tr><td>キャラの向き補間がおかしい</td><td>オイラー角→クォータニオンslerp</td></tr><tr><td>描画順ソート(マテリアル・深度)</td><td>基数ソート・ソートキー設計</td></tr><tr><td>エフェクトの「気持ちよさ」</td><td>イージング・補間</td></tr><tr><td>NPCの経路探索</td><td>A*・ナビメッシュ(発展)</td></tr><tr><td>リプレイが再現しない</td><td>乱数シード・決定性</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>generation付きハンドル配列(create/destroy/resolve)を実装し、 解放済みハンドルへのアクセスが安全に検出されることを確認せよ。</li><li>10万オブジェクトの近傍判定を(a)総当たり(b)ユニフォームグリッドで 実装し、速度を比較せよ。</li><li>A*で2Dグリッド迷路のパス検索を実装し、ヒューリスティックの 有無(=ダイクストラ)と比較せよ。</li><li>4x4行列クラス(乗算・逆行列・透視射影)を自作し、 「立方体をワイヤーフレームでスクリーン座標に投影して描く」 プログラムを書け(GPUなし、CPUだけで。第12章の最高の準備)。</li><li>クォータニオンクラス(乗算・slerp・行列変換)を自作し、 オイラー角のジンバルロックを実際に再現してから解決せよ。</li><li>内積だけで「敵が自分の視野角120度以内にいるか」を判定する関数を書け。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『実例で学ぶゲーム3D数学』(3D Math Primer)── ゲーム数学の定番。 規約(行/列)の説明が丁寧</li><li>『ゲームプログラミングのためのリアルタイム衝突判定』Christer Ericson ── 空間分割・交差判定の聖典。辞書使いでOK</li><li>『Game Programming Gems』シリーズ ── 拾い読み</li><li>螺旋本/蟻本などの競プロ本は<strong>不要</strong>(A*とグラフ基礎はゲーム書で足りる)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>HandmadeMath / GLM</strong> ── 数学ライブラリの実装を読む(自作後に比較)</li><li>DirectXMath(SIMD化された実物、Microsoft公式)</li><li>Recast/Detour ── ナビメッシュの業界標準(存在を知り、READMEを読む)</li><li>Box2D ── 衝突判定コードの美しい実例(発展編で本格読解)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Freya Holmér &quot;Math for Game Devs&quot; シリーズ ── ゲーム数学動画の最高峰</li><li>3Blue1Brown「線形代数の本質」── 行列の幾何的直観</li><li>GDC &quot;Math for Game Programmers&quot; シリーズ(毎年ある。過去回含め宝の山)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>GLMの <code>quaternion.hpp</code>、DirectXMathの <code>XMMatrixPerspectiveFovLH</code> (自作した後に読むと全て分かる)</li><li>Box2Dの <code>b2DynamicTree.cpp</code>(BVHの実物)</li><li>UE5 <code>FTransform</code>(回転をクォータニオンで持つ実物)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>内積が正/0/負のとき幾何的に何を意味するか。視野判定への応用は?</li><li>swap-and-pop削除の実装と、使ってよい条件(順序不問)を述べよ。</li><li>MVP変換の各行列は何から何座標系への変換か。</li><li>法線の変換に逆転置行列が必要なのはなぜか。</li><li>ジンバルロックとは何か。クォータニオンはなぜそれを回避できるか。</li><li>O(n²)の衝突判定を空間分割がどう改善するか。グリッドの弱点は?</li><li>「距離が10以下か」の判定でsqrtを避ける書き方は?</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1フレームの中の本章</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 入力→ 移動計算: ベクトル正規化・カメラ相対変換        │</span></span>
<span class="line"><span>│ AI  → A*パス検索・視野判定(内積)                    │</span></span>
<span class="line"><span>│ 物理→ グリッド/BVHで候補絞り→AABB/球判定→SAT        │</span></span>
<span class="line"><span>│ アニメ→ クォータニオンslerp→ボーン行列合成            │</span></span>
<span class="line"><span>│ カメラ→ ビュー行列・射影行列を構築                    │</span></span>
<span class="line"><span>│ カリング→ フラスタム6平面 vs AABB                    │</span></span>
<span class="line"><span>│ 描画→ ソートキーで基数ソート→MVP行列をGPUへ(第12章)  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span>
<span class="line"><span>シェーダ内の mul(pos, MVP) は、この章の行列連鎖そのもの</span></span></code></pre></div>`,31)])])}const g=a(r,[["render",s]]);export{c as __pageData,g as default};
